let exportOptions={format:'markdown',start:'2026-10-01',end:'2026-10-31',kind:'all',ai:false,game:false};
function myPage(){const profile=state.preview.profile,model=state.preview.ai;return heading('我的','个人设置各有入口，日常记录留在日常。')+`<section class="card"><div class="row between"><div><h2>${esc(profile.name)}</h2><p class="small muted">${esc(profile.username)} · Asia/Shanghai</p></div><span class="badge ${state.preview.role==='admin'?'amber':'gray'}">${state.preview.role==='admin'?'管理体验身份':'日常账号'}</span></div><div class="stat-mini"><div><strong>${recordDays('diary').total}</strong><span>日记天数</span></div><div><strong>${recordDays('event').total}</strong><span>事件记录天数</span></div><div><strong>${balance()}</strong><span>示例金币</span></div></div></section><div class="suite-grid" style="margin-top:20px"><section class="card"><button class="menu-row" data-nav="settings"><span class="menu-symbol">${svg('spark')}</span><div><strong>模型与 AI</strong><span class="muted">${esc(modelCaption())}</span><span class="muted">${model.source==='off'?'记录不受影响':model.status==='ready'?'示例状态：可用':'已保存 · 需要验证'}</span></div><span>→</span></button><button class="menu-row" data-nav="security"><span class="menu-symbol">${svg('check')}</span><div><strong>账号与安全</strong><span class="muted">密码、邮箱与设备会话</span></div><span>→</span></button><button class="menu-row" data-nav="export"><span class="menu-symbol">${svg('review')}</span><div><strong>导出与本地保存</strong><span class="muted">原文、完整问答或业务存档</span></div><span>→</span></button></section><section class="card"><button class="menu-row" data-nav="preview"><span class="menu-symbol">${svg('guide')}</span><div><strong>审阅这一版</strong><span class="muted">查看待确认选项，记下你的意见</span></div><span>→</span></button>${state.preview.role==='admin'?'<button class="menu-row" data-nav="admin"><span class="menu-symbol">'+svg('date')+'</span><div><strong>管理后台</strong><span class="muted">公告与站点选项的候选体验</span></div><span>→</span></button>':''}<button class="menu-row" data-nav="auth"><span class="menu-symbol">${svg('today')}</span><div><strong>体验登录与注册</strong><span class="muted">不创建真实账号或发送邮件</span></div><span>→</span></button></section></div>`;}
function statusLabel(model){return {ready:'示例测试通过',unverified:'已保存 · 尚未验证',failed:'测试失败',testing:'正在测试'}[model.status]||'尚未配置';}
function modelSettings(){const config=state.preview.ai,own=config.source==='own';return `<button class="link-btn" data-nav="my">← 返回我的</button>`+heading('模型与 AI','看得见当前使用什么，也可以随时关闭。')+candidateNote('站点默认 AI 是候选方案，模型、额度与运营预算尚未确认。所有测试结果均为脚本模拟。')+`<div class="suite-grid"><section class="card"><h2>选择 AI 来源</h2><div class="source-choices"><button class="source-choice" data-model-source="site" aria-pressed="${config.source==='site'}"><strong>站点默认 AI <span class="candidate">候选</span></strong><span>免填 Key，按站点额度使用；额度待确认。</span></button><button class="source-choice" data-model-source="own" aria-pressed="${own}"><strong>我自己的模型</strong><span>使用自己的供应商账号和 API 配置。</span></button><button class="source-choice" data-model-source="off" aria-pressed="${config.source==='off'}"><strong>关闭 AI</strong><span>仍能记录、回看、手写日记与导出。</span></button></div><div class="model-summary"><p class="model-label">当前已保存配置 · ${config.source==='site'?'站点默认':own?'我的模型':'AI 关闭'}</p><h3>${config.source==='off'?'未启用模型':esc(config.model||'尚未配置')}</h3><p>${config.source==='off'?'不发起分析':esc(providers[config.provider].name)}</p><p id="model-saved-status">${config.source==='off'?'无模型也能记录':statusLabel(config)}</p></div>${config.source==='site'?'<p class="subtle-note">首次启用时需说明哪些内容发送给哪家模型服务。免费不代表无限调用；不可用时不会自动切换收费模型。</p>':''}<button class="link-btn" data-nav="guide" style="margin-top:15px">第一次配置？查看步骤与官方入口 →</button></section><section class="card">${own?`<div class="section-head"><h2>编辑自己的配置</h2><span id="model-draft-label" class="badge gray">已保存内容</span></div><div class="form-grid"><label>供应商<select id="model-provider">${Object.entries(providers).map(([id,provider])=>`<option value="${id}" ${config.provider===id?'selected':''}>${provider.name}</option>`).join('')}</select></label><label>模型 ID<input id="model-name" value="${esc(config.model)}" placeholder="从官方模型列表复制完整 ID"></label><label>API Key<input disabled value="Demo 不采集真实 Key" aria-label="Demo 不填写真实密钥"></label><p class="input-help">只体验保存和验证流程，不要在 Demo 填真实密钥。</p><div class="row wrap"><button class="btn primary" data-suite="save-model">保存配置</button><button class="btn" data-suite="test-model" ${config.status==='testing'?'disabled':''}>${config.status==='testing'?'示例测试中…':'测试已保存配置'}</button></div><div id="model-error" class="error-box" role="alert" hidden></div><div id="model-success" class="success-box" role="status" hidden></div><button class="link-btn" data-suite="valid-model-example">填入一组可通过的示例</button></div>`:`<h2>${config.source==='off'?'记录由你自己掌握':'开箱即用的候选体验'}</h2><p class="dashboard-quote">${config.source==='off'?'需要 AI 时，再主动选择模型来源。已有原文与历史分析不会删除。':'可以先尝试站点提供的模型，不必把 API 配置当成写日记的前提。'}</p><ul class="guidance-list"><li>日记原文、你的回答与 AI 分析分开展示。</li><li>不自动分析所有历史内容。</li><li>免费项失效时保留原文，允许稍后再试。</li></ul><div class="record-actions"><button class="btn soft" data-nav="review">去晚间日记看看</button></div>`}</section></div>`;}
function modelMessage(kind,text){const target=document.getElementById(kind==='error'?'model-error':'model-success');if(!target)return;document.getElementById(kind==='error'?'model-success':'model-error').hidden=true;target.textContent=text;target.hidden=false;}
function securityPage(){return `<button class="link-btn" data-nav="my">← 返回我的</button>`+heading('账号与安全','主动改密与忘记密码，各有清楚的入口。')+candidateNote('这里预览邮箱验证与邮件找回方案；正式接入服务、会话策略仍待确认。不使用真实密码。')+`<div class="suite-grid"><section class="card"><h2>我的账号</h2><div class="info-line"><span>用户名</span><strong>${esc(state.preview.profile.username)}</strong></div><div class="info-line"><span>邮箱</span><strong>${esc(state.preview.profile.email)}</strong></div><div class="info-line"><span>邮箱状态</span><span class="badge green">已验证 · 示例</span></div><div class="record-actions"><button class="btn" data-suite="change-password">修改密码</button><button class="btn quiet" data-suite="change-email">更换邮箱</button></div></section><section class="card"><h2>设备与恢复</h2><div class="info-line"><span>本机浏览器</span><span class="badge green">当前设备 · 示例</span></div><div class="info-line"><span>其他设备</span><span class="small muted">${state.preview.otherSessions??1} 个示例会话</span></div><button class="link-btn" data-suite="logout-devices">退出其他设备</button><p class="subtle-note">找回密码可以使用已验证邮箱，恢复码是否作为备用入口仍待确认。</p><button class="link-btn" data-auth-tab="forgot" data-nav="auth">体验忘记密码 →</button></section></div>`;}
function authPage(){const register=authTab==='register',forgot=authTab==='forgot';return `<section class="card auth-card"><p class="eyebrow">游戏人生 · LifeXP</p><h1>${forgot?'找回密码':register?'给自己留一页':'欢迎回来'}</h1><p>${forgot?'使用已验证邮箱恢复账号。':register?'先创建账号，模型可以以后再配。':'记录小事，慢慢看见自己的积累。'}</p><div class="auth-demo">候选流程演示，不发送邮件、不创建真实账号。请使用示例值，不填写真实密码。</div><div class="form-grid">${forgot?'<label>已验证邮箱<input id="auth-email" type="email" value="friend@example.com"></label>':`${register?'<label>用户名<input id="auth-username" value="preview_friend" maxlength="30"></label><label>邮箱<input id="auth-email" type="email" value="friend@example.com"></label>':'<label>用户名或邮箱<input id="auth-username" value="xiaolin"></label>'}<label>示例密码<input id="auth-password" type="password" value="demo-password-123" autocomplete="off"></label>${register?'<label>确认示例密码<input id="auth-password-confirm" type="password" value="demo-password-123" autocomplete="off"></label>':''}`}<button class="btn primary full" data-suite="auth-submit">${forgot?'模拟发送重设链接':register?'体验注册':'使用示例账号进入'}</button><div id="auth-error" class="error-box" hidden></div></div><div class="auth-footer">${!forgot?`<button class="link-btn" data-auth-tab="${register?'login':'register'}">${register?'已有账号，去登录':'创建账号'}</button><button class="link-btn" data-auth-tab="forgot">忘记密码</button>`:'<button class="link-btn" data-auth-tab="login">返回登录</button>'}<button class="link-btn" data-nav="preview">返回体验目录</button></div><p class="subtle-note">注册无需邀请码。手机、QQ 或微信绑定暂不作为已选定功能。</p></section>`;}
function exportPage(){return `<button class="link-btn" data-nav="my">← 返回我的</button>`+heading('导出与本地保存','选好内容，留一份自己能打开的记录。')+candidateNote('格式与默认范围供你体验选择。这些文件只含虚构示例，不是服务器备份或正式迁移包。')+`<div class="suite-grid"><section class="card"><h2>选择导出内容</h2><div class="form-grid"><label>文件格式<select id="export-format"><option value="markdown" ${exportOptions.format==='markdown'?'selected':''}>Markdown · 本地阅读和整理</option><option value="html" ${exportOptions.format==='html'?'selected':''}>HTML · 浏览器离线阅读</option><option value="json" ${exportOptions.format==='json'?'selected':''}>JSON · 完整业务存档</option><option value="csv" ${exportOptions.format==='csv'?'selected':''}>CSV · 原文表格</option></select></label><label>记录范围<select id="export-kind"><option value="all">事件与日记</option><option value="event">只导出事件</option><option value="diary">只导出日记</option></select></label><div class="suite-grid"><label>开始日期<input id="export-start" type="date" value="${exportOptions.start}"></label><label>结束日期<input id="export-end" type="date" value="${exportOptions.end}"></label></div><label class="checkbox-label"><input id="export-ai" type="checkbox" ${exportOptions.ai?'checked':''}>包含完整 AI 问答与分析</label><label class="checkbox-label"><input id="export-game" type="checkbox" ${exportOptions.game?'checked':''} ${exportOptions.format!=='json'?'disabled':''}>包含金币、属性、成就与奖励券（JSON）</label><div class="row wrap"><button class="btn" data-suite="export-preview">预览内容</button><button class="btn primary" data-suite="export-download">下载示例文件</button></div><div id="export-error" class="error-box" hidden></div></div></section><section class="card"><h2>这份文件里有什么？</h2><p class="dashboard-quote">阅读用的文件可以只保留原文。勾选 AI 后，问题、你的回答和分析分别标注，不混入日记正文。</p><div class="info-line"><span>Markdown / HTML</span><span>按日期阅读原文</span></div><div class="info-line"><span>JSON</span><span>结构化记录与可选游戏数据</span></div><div class="info-line"><span>CSV</span><span>原文及可选辅助记录列</span></div><p class="subtle-note">不包含 API Key、密码、会话凭据。导出不等于已实现反向导入。</p><pre id="export-content" class="export-preview" hidden></pre></section></div>`;}
function publicSession(session){return {startedAt:session.startedAt,endedAt:session.endedAt||null,model:session.model,state:session.state,diarySnapshot:session.snapshot?.diary||null,turns:session.turns.map(turn=>({questionId:turn.id,question:turn.question,askedAt:turn.askedAt,state:turn.state,answer:turn.answer,answeredAt:turn.answeredAt})),analysis:session.analysis};}
function buildExport(options=exportOptions){
  const records=state.records.filter(record=>record.date>=options.start&&record.date<=options.end&&(options.kind==='all'||(options.kind==='diary'?record.kind==='diary':record.kind!=='diary'))).sort((a,b)=>a.date.localeCompare(b.date));
  const rows=records.map(record=>({id:record.id,date:record.date,time:record.time,type:record.kind==='diary'?'diary':'event',title:record.title,original:record.content,supplement:record.supplement||'',...options.ai?{review:(state.reviewDays[record.date]?.sessions||[]).filter(()=>record.kind==='diary').map(publicSession),eventAnalysis:record.kind!=='diary'?record.suggestion||null:null}:{}}));
  const archive={scope:'LifeXP 本机虚构 Demo',exportedAt:new Date().toISOString(),records:rows,...options.game&&options.format==='json'?{game:{attributes:Object.fromEntries(dimensions.map(name=>[name,attributeValue(name)])),coinBalance:balance(),coinLedger:walletRows(),achievements:state.preview.claimed,rewardVouchers:state.preview.vouchers,goals:state.preview.goals,plans:state.plans}}:{}};
  const transcript=row=>(row.review||[]).map(session=>`\n### AI 辅助回顾 · ${session.startedAt||'历史示例'}\n${session.turns.map(turn=>`\n**AI 提问：** ${turn.question}\n\n**我的回答：** ${turn.state==='skipped'?'已跳过':turn.state==='asked'?'尚未回答':turn.answer}\n`).join('')}${session.analysis?'\n**AI 分析（示例）：** '+session.analysis.text+'\n':''}`).join('')+(row.eventAnalysis?`\n### AI 事件分析（示例）\n\n${row.eventAnalysis.reason}\n\n属性建议：${row.eventAnalysis.attribute} +${row.eventAnalysis.delta}；金币建议：${row.eventAnalysis.coins} 币（示例）。\n`:'');
  const markdown='# LifeXP · 我的记录\n\n虚构 Demo 导出\n'+rows.map(row=>`\n## ${row.date} · ${row.type==='diary'?'日记':'事件'}\n\n### ${row.title}\n\n**我的原文**\n\n${row.original}\n${row.supplement?'\n**我的补充**\n\n'+row.supplement+'\n':''}${options.ai?transcript(row):''}`).join('');
  if(options.format==='json')return {name:'LifeXP-示例存档.json',type:'application/json;charset=utf-8',text:JSON.stringify(archive,null,2)};
  if(options.format==='csv'){const cell=value=>{let text=String(value??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};return {name:'LifeXP-示例原文.csv',type:'text/csv;charset=utf-8',text:'\uFEFF'+[['类型','日期','标题','我的原文','我的补充',...(options.ai?['辅助回顾问答与分析']:[])],...rows.map(row=>[row.type,row.date,row.title,row.original,row.supplement,...(options.ai?[JSON.stringify({review:row.review,eventAnalysis:row.eventAnalysis})]:[])])].map(row=>row.map(cell).join(',')).join('\r\n')};}
  if(options.format==='html')return {name:'LifeXP-示例日记.html',type:'text/html;charset=utf-8',text:'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>LifeXP · 本地记录</title><style>body{max-width:760px;margin:40px auto;padding:24px;font:16px/1.9 sans-serif;color:#293047}pre{white-space:pre-wrap;overflow-wrap:anywhere}article{border-bottom:1px solid #ddd;padding:20px 0}</style><h1>LifeXP · 本地记录</h1><p>虚构 Demo 导出</p>'+rows.map(row=>`<article><p>${esc(row.date)} · ${row.type==='diary'?'日记':'事件'}</p><h2>${esc(row.title)}</h2><h3>我的原文</h3><pre>${esc(row.original)}</pre>${row.supplement?'<h3>我的补充</h3><pre>'+esc(row.supplement)+'</pre>':''}${options.ai?'<pre>'+esc(transcript(row))+'</pre>':''}</article>`).join('')+'</html>'};
  return {name:'LifeXP-示例日记.md',type:'text/markdown;charset=utf-8',text:markdown};
}
function readExportForm(){exportOptions={format:document.getElementById('export-format').value,kind:document.getElementById('export-kind').value,start:document.getElementById('export-start').value,end:document.getElementById('export-end').value,ai:document.getElementById('export-ai').checked,game:document.getElementById('export-game').checked};if(!exportOptions.start||!exportOptions.end||exportOptions.start>exportOptions.end){const box=document.getElementById('export-error');box.textContent='请选择有效的起止日期。';box.hidden=false;return false;}return true;}
function downloadArtifact(artifact){const url=URL.createObjectURL(new Blob([artifact.text],{type:artifact.type})),link=document.createElement('a');link.href=url;link.download=artifact.name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function adminPage(){if(state.preview.role!=='admin')return heading('管理入口','日常账号不显示管理功能。')+`<section class="card"><p class="dashboard-quote">你现在体验的是普通日常账号。要查看候选管理界面，可到审阅页切换虚构管理身份。</p><button class="btn" data-nav="preview">切换体验身份</button></section>`;const notice=state.preview.notice;return heading('管理后台','管理身份用于站点事务，日常记录使用自己的账号。')+candidateNote('首批管理范围尚未确认。这里不展示其他人的日记、密钥或改账入口。')+`<div class="suite-grid"><section class="card"><div class="section-head"><h2>站点公告</h2><span class="badge ${notice.published?'green':'gray'}">${notice.published?'示例已发布':'未发布'}</span></div><div class="form-grid"><label>标题<input id="notice-title" value="${esc(notice.title)}" maxlength="100"></label><label>公告内容<textarea id="notice-body" maxlength="2000">${esc(notice.body)}</textarea></label><div class="row wrap"><button class="btn" data-suite="preview-notice">预览</button><button class="btn primary" data-suite="publish-notice">发布到本机示例</button><button class="btn quiet" data-suite="withdraw-notice">撤下</button></div></div></section><section class="card"><h2>注册与账号状态</h2><div class="info-line"><span>开放注册 · 候选</span><button class="toggle" data-suite="toggle-registration" role="switch" aria-checked="${state.preview.registrationOpen}" aria-label="开放注册"></button></div><div class="info-line"><div><strong>preview_friend</strong><p class="small muted">普通示例账号</p></div><button class="btn small-btn" data-suite="pause-account">${state.preview.accountPaused?'恢复示例状态':'停用示例状态'}</button></div><p class="subtle-note">这些操作只改本机虚构状态，不修改真实账号或服务器。</p><div class="review-divider"></div><h3>操作记录</h3><div class="mini-timeline"><p>${notice.published?'公告已在本机预览发布':'公告已撤下或尚未发布'}</p><p>注册${state.preview.registrationOpen?'开放':'关闭'} · 示例</p><p>不提供查看个人日记或 API Key 的按钮。</p></div></section></div>`;}
function showProductForm(id){const product=state.preview.products.find(product=>product.id===id);showPreviewDialog(product?'调整奖励价格':'添加想要的东西',`<div class="form-grid"><label>名称<input id="product-name" value="${esc(product?.name||'')}" maxlength="100" placeholder="例如：留半小时读小说"></label><label>现实价格（元，可填 0）<input id="product-yuan" type="number" min="0" value="${product?.yuan||0}"></label><label>金币价格 · 示例<input id="product-coins" type="number" min="1" step="1" value="${product?.coins||12}"></label></div>`,()=>{const name=document.getElementById('product-name').value.trim(),yuan=Number(document.getElementById('product-yuan').value),coins=Number(document.getElementById('product-coins').value);if(!name||!Number.isFinite(yuan)||yuan<0||!Number.isInteger(coins)||coins<1){modalError('请填写名称、非负现实价格和正整数金币。');return;}if(product)Object.assign(product,{name,yuan,coins});else state.preview.products.push({id:crypto.randomUUID(),name,yuan,coins});persist();closePreviewDialog();render();},'保存示例');}
function handleSettingsAction(action){
  if(action==='save-model'){const model=document.getElementById('model-name').value.trim(),provider=document.getElementById('model-provider').value;if(!model){modelMessage('error','请填写准确的模型 ID。');return;}state.preview.ai={source:'own',provider,model,status:'unverified',version:state.preview.ai.version+1};state.preview.ownModel={...state.preview.ai};persist();render();modelMessage('success','配置已保存，尚未验证；保存不代表模型可用。');return;}
  if(action==='valid-model-example'){document.getElementById('model-provider').value='deepseek';document.getElementById('model-name').value='deepseek-chat';document.getElementById('model-draft-label').textContent='未保存修改';return;}
  if(action==='test-model'){const config=state.preview.ai;if(config.source!=='own')return;if(document.getElementById('model-name').value.trim()!==config.model||document.getElementById('model-provider').value!==config.provider){modelMessage('error','请先保存当前修改，再测试已保存的配置。');return;}config.status='testing';const version=config.version;persist();render();setTimeout(()=>{if(state.preview.ai!==config||state.preview.ai.version!==version||state.preview.ai.source!=='own')return;config.status=(config.provider==='deepseek'&&config.model==='deepseek-chat')||(config.provider==='siliconflow'&&config.model==='XingChenAGI/Xing4.0-29B')?'ready':'failed';state.preview.ownModel={...config};persist();if(currentPage==='settings'){render();modelMessage(config.status==='ready'?'success':'error',config.status==='ready'?'示例验证通过。真实 API 的权限、费用和输出能力仍需正式测试。':'示例错误：找不到这个模型。请核对供应商和完整模型 ID，原配置与输入已保留。');}},350);return;}
  if(action==='change-password'||action==='reset-password'){const recovery=action==='reset-password';showPreviewDialog(recovery?'重设密码 · 仅演示':'修改密码 · 仅演示','<div class="auth-demo">不要填写真实密码；这里不会保存密码或修改正式账号。</div><div class="form-grid">'+(recovery?'':'<label>当前示例密码<input id="password-old" type="password" autocomplete="off"></label>')+'<label>新示例密码<input id="password-new" type="password" autocomplete="off"></label><label>确认新示例密码<input id="password-confirm" type="password" autocomplete="off"></label></div>',()=>{const old=document.getElementById('password-old')?.value,next=document.getElementById('password-new').value,confirm=document.getElementById('password-confirm').value;if((!recovery&&!old)||next.length<12||next!==confirm){modalError(recovery?'新示例密码至少 12 个字符，且两次一致。':'请填写当前示例密码；新密码至少 12 个字符，且两次一致。');return;}closePreviewDialog();toast('示例改密流程完成，没有修改真实账号。');},'确认演示');return;}
  if(action==='change-email'){showPreviewDialog('更换邮箱 · 候选','<p class="dashboard-quote">正式流程需要验证本人身份和新邮箱，不只是填写地址。这里不发送邮件。</p><div class="form-grid"><label>示例新邮箱<input id="new-email" value="new-friend@example.com" type="email"></label></div>',()=>{const email=document.getElementById('new-email').value;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){modalError('请填写有效的示例邮箱。');return;}state.preview.profile.email=email;persist();closePreviewDialog();render();toast('模拟验证完成，只更新本机示例。');},'模拟验证完成');return;}
  if(action==='logout-devices'){showPreviewDialog('退出其他设备？','<p class="dashboard-quote">正式实现会撤销其他设备会话。这里仅体验确认流程，当前页面会继续保留。</p>',()=>{state.preview.otherSessions=0;persist();closePreviewDialog();render();toast('示例操作完成，没有影响真实设备。');});return;}
  if(action==='auth-submit'){if(authTab==='login'){setPage('today');return;}const email=document.getElementById('auth-email').value;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){const box=document.getElementById('auth-error');box.textContent='请填写有效的示例邮箱。';box.hidden=false;return;}if(authTab==='forgot'){showPreviewDialog('邮件找回流程 · 演示','<p class="dashboard-quote">如果该邮箱已注册，会收到有时限的一次性重设链接。此处不发送邮件，也不暴露账号是否存在。</p>',()=>{closePreviewDialog();handleSettingsAction('reset-password');},'继续体验重设');return;}const password=document.getElementById('auth-password').value,confirm=document.getElementById('auth-password-confirm').value,username=document.getElementById('auth-username').value.trim();if(!/^[A-Za-z0-9_]{3,30}$/.test(username)||password.length<12||password!==confirm){const box=document.getElementById('auth-error');box.textContent='用户名用 3～30 位字母、数字或下划线；示例密码至少 12 字符且两次一致。';box.hidden=false;return;}if(!state.preview.registrationOpen){const box=document.getElementById('auth-error');box.textContent='站点示例目前关闭注册。';box.hidden=false;return;}showPreviewDialog('验证邮箱 · 流程演示','<p class="dashboard-quote">正式注册会验证你控制这个邮箱；这里不会真的创建账号或发送邮件。</p>',()=>{state.preview.profile.username=username;state.preview.profile.email=email;persist();closePreviewDialog();setPage('my');},'模拟完成验证');return;}
  if(action==='export-preview'||action==='export-download'){if(!readExportForm())return;const artifact=buildExport();if(action==='export-download')downloadArtifact(artifact);else{const output=document.getElementById('export-content');output.textContent=artifact.text.slice(0,6000);output.hidden=false;}return;}
  if(['preview-notice','publish-notice','withdraw-notice','toggle-registration','pause-account'].includes(action)&&state.preview.role!=='admin')return;
  if(action==='preview-notice'){showPreviewDialog('公告预览',`<h3 style="margin-top:17px">${esc(document.getElementById('notice-title').value)}</h3><p class="dashboard-quote">${esc(document.getElementById('notice-body').value)}</p>`,closePreviewDialog,'看完了');return;}
  if(action==='publish-notice'){const title=document.getElementById('notice-title').value.trim(),body=document.getElementById('notice-body').value.trim();if(!title||!body){toast('先补全标题和公告内容。');return;}state.preview.notice={title,body,published:true,version:state.preview.notice.version+1};persist();render();return;}
  if(action==='withdraw-notice'){state.preview.notice.published=false;persist();render();return;}
  if(action==='toggle-registration'){state.preview.registrationOpen=!state.preview.registrationOpen;persist();render();return;}
  if(action==='pause-account'){state.preview.accountPaused=!state.preview.accountPaused;persist();render();return;}
}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button?.dataset.modelSource)return;event.stopImmediatePropagation();const source=button.dataset.modelSource;if(source==='own'){state.preview.ownModel ||= {provider:'deepseek',model:'deepseek-chat',status:'unverified',version:1};state.preview.ai={...state.preview.ownModel,source};}else state.preview.ai={source,provider:'siliconflow',model:'XingChenAGI/Xing4.0-29B',status:source==='off'?'off':'ready',version:state.preview.ai.version+1};persist();render();},true);
document.addEventListener('input',event=>{if(['model-name','model-provider'].includes(event.target.id)){const label=document.getElementById('model-draft-label');if(label)label.textContent='未保存修改';}});
document.addEventListener('change',event=>{if(event.target.id==='export-format'){if(!readExportForm())return;render();}if(event.target.id==='model-provider'){const label=document.getElementById('model-draft-label');if(label)label.textContent='未保存修改';}});
